import java.util.*;

class Solution {
  public int maxBoxesInWarehouse(int[] boxes, int[] warehouse) {
    int n = warehouse.length;
    int[] limit = new int[n]; // a room only admits what fits through every room before it
    for (int i = 0; i < n; i++) limit[i] = i == 0 ? warehouse[0] : Math.min(limit[i - 1], warehouse[i]);
    Arrays.sort(boxes);
    int count = 0;
    for (int room = n - 1; room >= 0 && count < boxes.length; room--) if (boxes[count] <= limit[room]) count++;
    return count;
  }
}
